const task = $input.first().json;

// 兼容两种情况：
// 1. Wait 回调后的数据在 body 里
// 2. 上游直接传入数据
const data = task?.body || task;

// 从灵智 AI 网关的 output.text 中提取模型输出
const raw =
  data?.output?.text ||
  data?.output?.content ||
  data?.output?.message ||
  "";

if (data?.status !== "Succeeded" || !String(raw).trim()) {
  return [{
    json: {
      errorCode: "ANALYSIS_FAILED",
      message: data?.errorMessage || "视频拆解失败",
      videoBlueprint: ""
    }
  }];
}

// 清理 Gemini / GPT 可能返回的 Markdown JSON 代码块
const text = String(raw)
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  return [{
    json: {
      errorCode: "PARSE_FAILED",
      message: "拆解模型 output.text 无法解析为 JSON",
      parseError: error.message,
      rawOutput: raw,
      videoBlueprint: ""
    }
  }];
}

// 模型标准输出结构：
// {
//   "videoBlueprint": {...}
// }
//
// 如果模型直接返回 videoBlueprint 本体，也兼容
const videoBlueprint =
  parsed?.videoBlueprint ?? parsed;

if (
  !videoBlueprint ||
  typeof videoBlueprint !== "object" ||
  Array.isArray(videoBlueprint)
) {
  return [{
    json: {
      errorCode: "INVALID_VIDEO_BLUEPRINT",
      message: "output.text 中缺少有效的 videoBlueprint",
      rawOutput: parsed,
      videoBlueprint: ""
    }
  }];
}

const input = $("Webhook").first().json.body.input || {};
if (String(input.plannerVersion || "1") === "2") {
  try { validateBlueprintV2(videoBlueprint, input.userConfig?.targetDuration); }
  catch (error) { return [{json:{errorCode:"INVALID_BLUEPRINT_V2",message:error.message,videoBlueprint:""}}]; }
}

return [{
  json: {
    callbackUrl:
      $("Webhook").first().json.body.callbackUrl || "",

    benchmarkVideoUrl:
      input.benchmarkVideo?.url ||
      input.benchmarkVideoUrl ||
      "",

    userConfig:
      input.userConfig || {},

    // Planner版本属于服务端协议，不注入Gemini Prompt。
    plannerVersion:
      String(input.plannerVersion || "1"),

    // 下游提示词目前直接使用：
    // {{ $json.videoBlueprint }}
    // 所以这里转成 JSON 字符串，避免变成 [object Object]
    videoBlueprint:
      JSON.stringify(videoBlueprint)
  }
}];
// Appended to the versioned n8n Planner node. V1 remains unchanged.
function validateBlueprintV2(bp, duration) {
  const fail = message => { throw new Error(message); };
  const number = x => typeof x === 'number' && Number.isFinite(x);
  const roster = (items, key) => {
    if (!Array.isArray(items)) fail(key + '清单必须是数组');
    const map = new Map();
    for (const item of items) {
      const id = item?.[key];
      if (typeof id !== 'string' || !id.trim() || map.has(id)) fail(key + '缺失或重复');
      map.set(id, item);
    }
    return map;
  };
  const ids = (list, known, name) => {
    if (!Array.isArray(list) || new Set(list).size !== list.length || list.some(x => typeof x !== 'string' || !known.has(x))) fail(name + '无效或引用不存在的ID');
    return list;
  };
  if (bp.schemaVersion !== '7.0') fail('V2要求Blueprint 7.0');
  const people = roster(bp['视频元素']?.['人物'], 'characterId');
  const products = roster(bp['视频元素']?.['产品'], 'productId');
  const voices = roster(bp['声音结构']?.voiceProfiles, 'speakerId');
  for (const voice of voices.values()) {
    if (voice.characterId != null && !people.has(voice.characterId)) fail('声源关联不存在的人物');
  }
  const shots = bp['逐镜头拆解'];
  roster(shots, 'shotId');
  if (!shots.length) fail('缺少逐镜头拆解');
  let cursor = 0;
  const seenPeople = new Set(), seenProducts = new Set(), utterances = new Set();
  for (const shot of shots) {
    const {start:a, end:b} = shot;
    if (!number(a) || !number(b) || b <= a || Math.abs(a-cursor) > .05) fail('镜头时间无效或存在空档/重叠');
    cursor = b;
    ids(shot.visibleCharacterIds, people, 'visibleCharacterIds').forEach(x => seenPeople.add(x));
    ids(shot.productIds, products, 'productIds').forEach(x => seenProducts.add(x));
    if (!Array.isArray(shot.keyframes) || !shot.keyframes.length) fail('缺少keyframes');
    for (const frame of shot.keyframes) if (!number(frame.time) || frame.time < a || frame.time >= b) fail('keyframe越界');
    if (!Array.isArray(shot['声音']?.utterances)) fail('utterances必须是数组');
    for (const line of shot['声音'].utterances) {
      if (typeof line.utteranceId !== 'string' || !line.utteranceId || utterances.has(line.utteranceId) || !voices.has(line.speakerId)) fail('utteranceId重复/缺失或speakerId不存在');
      utterances.add(line.utteranceId);
      if (!number(line.start) || !number(line.end) || !(a <= line.start && line.start < line.end && line.end <= b)) fail('对白时间越界');
    }
  }
  if (!number(duration) || Math.abs(cursor-duration) > .1) fail('蓝图未覆盖目标时长');
  if (people.size !== seenPeople.size || products.size !== seenProducts.size) fail('实体清单与镜头引用不一致');
  for (const [id, person] of people) {
    const t = person.referenceTime;
    if (!number(t) || !shots.some(s => s.start <= t && t < s.end && s.visibleCharacterIds.includes(id))) fail('人物referenceTime未落在其出镜镜头');
  }
  const cuts = bp['节奏结构']?.cutPlan;
  if (!Array.isArray(cuts) || cuts.length !== shots.length-1) fail('cutPlan未覆盖相邻镜头');
  cuts.forEach((c,i) => {
    if (!number(c.time) || Math.abs(c.time-shots[i+1].start) > .05 || c.fromShotId !== shots[i].shotId || c.toShotId !== shots[i+1].shotId) fail('cutPlan边界引用错误');
  });
}

const input = $input.first().json || {};
const callbackUrl = $("Webhook").first().json.body.callbackUrl || "";

let videoBlueprint = input.videoBlueprint || "";
if (typeof videoBlueprint === "string" && videoBlueprint.trim()) {
  try { videoBlueprint = JSON.parse(videoBlueprint); } catch (_) { videoBlueprint = null; }
}
const replicationPlan = input.replicationPlan;

const success =
  !input.errorCode &&
  videoBlueprint && typeof videoBlueprint === "object" && !Array.isArray(videoBlueprint) &&
  replicationPlan && typeof replicationPlan === "object" && !Array.isArray(replicationPlan) &&
  Array.isArray(replicationPlan.segments) && replicationPlan.segments.length > 0;

const result = {
  success,
  output: success ? { videoBlueprint, replicationPlan } : {},
  credits: success ? Number($('提交积分消费').first().json.__credits) : 0,
  errorCode: success ? "" : (input.errorCode || "ANALYSIS_OR_PLANNING_FAILED"),
  errorMessage: success ? "" : (input.errorMessage || input.message || input.errorCode || "视频拆解或复刻规划失败")
};

if (!callbackUrl) {
  return [{ json: { status: "error", success: false, credits: 0, errorMessage: "callbackUrl为空" } }];
}

await helpers.httpRequest({
  method: "POST",
  url: callbackUrl,
  headers: { "Content-Type": "application/json" },
  body: result,
  json: true
});

return [{
  json: {
    status: "ok",
    success,
    credits: result.credits,
    errorMessage: result.errorMessage,
    plannerVersion: success ? replicationPlan.plannerVersion : "",
    planSchemaVersion: success ? replicationPlan.schemaVersion : "",
    policyVersion: success ? (replicationPlan.policyVersion || "") : ""
  }
}];

const input = $input.first().json || {};

const PLAN_SCHEMA_VERSION = '1.0';
const DEFAULT_PLANNER_VERSION = '1';

// Planner Engine 与 Policy 分离：
// - Engine 负责稳定算法与输出协议；
// - Policy 只保存可调参数。
// 兼容原则：同一个 plannerVersion 内不得删除/改名协议字段，
// 也不得改变已发布模型的 anchor 数量或合法时长范围；此类变化必须新增 Planner 版本。
const POLICIES = {
  '1': {
    policyVersion: '1.0.0',
    blueprintSchemaVersion: '6.0',
    models: {
      'seedance-2-mini':     { minDuration: 4, maxDuration: 15, anchorCount: 9 },
      'seedance-2-fast':     { minDuration: 4, maxDuration: 15, anchorCount: 9 },
      'seedance-2-fast-vip': { minDuration: 4, maxDuration: 15, anchorCount: 9 },
      'seedance-2':          { minDuration: 4, maxDuration: 15, anchorCount: 9 },
      'seedance-2-vip':      { minDuration: 4, maxDuration: 15, anchorCount: 9 },
      'seedance-2-5':        { minDuration: 4, maxDuration: 30, anchorCount: 9 }
    },
    scoring: {
      utteranceSplitPenalty: 5,
      boundaryDistanceWeight: 1,
      lengthBalanceWeight: 0.01
    },
    timing: {
      anchorMinDistance: 0.04,
      endSafetyMargin: 0.04,
      unresolvedCutTolerance: 0.5,
      sourceDurationTolerance: 0.500001
    }
  }
};

function asObject(value, label) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
    } catch (_) {}
  }
  throw new Error(label + '不是有效对象');
}

function finiteNumber(value, label = '时间') {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(label + '必须是有限数字秒');
  return Number(value);
}

function normalizeModel(value) {
  const raw = String(value || '').trim();
  const normalized = raw.toLowerCase().replace(/[_-]/g, ' ').replace(/\s+/g, ' ').trim();
  const aliases = {
    'seedance 2 mini': 'seedance-2-mini',
    'seedance2 mini': 'seedance-2-mini',
    'seedance2.0 mini': 'seedance-2-mini',
    'seedance 2 fast': 'seedance-2-fast',
    'seedance2 fast': 'seedance-2-fast',
    'seedance2.0 fast': 'seedance-2-fast',
    'seedance 2 fast vip': 'seedance-2-fast-vip',
    'seedance2 fast vip': 'seedance-2-fast-vip',
    'seedance 2': 'seedance-2',
    'seedance2': 'seedance-2',
    'seedance2.0': 'seedance-2',
    'seedance 2 vip': 'seedance-2-vip',
    'seedance2 vip': 'seedance-2-vip',
    'seedance 2.5': 'seedance-2-5',
    'seedance2.5': 'seedance-2-5',
    'seedance 2 5': 'seedance-2-5'
  };
  return aliases[normalized] || raw;
}

function capability(policy, model) {
  const id = normalizeModel(model);
  const limits = policy.models[id];
  if (!limits) throw new Error('当前Planner不支持的视频模型：' + id);
  return { model: id, ...limits };
}

function diagnose(bp, duration, policy) {
  const warnings = [];
  if (bp.reviewRequired) warnings.push('Gemini标记需要复核');
  if (bp.schemaVersion !== policy.blueprintSchemaVersion) warnings.push('蓝图schemaVersion不匹配');
  const shots = Array.isArray(bp['逐镜头拆解']) ? bp['逐镜头拆解'] : [];
  const profiles = Array.isArray(bp?.['声音结构']?.voiceProfiles) ? bp['声音结构'].voiceProfiles : [];
  const voices = profiles.filter(p => p && p.speakerId).map(p => p.speakerId);
  if (new Set(voices).size !== voices.length) warnings.push('speakerId重复');
  const people = new Set((Array.isArray(bp?.['视频元素']?.['人物']) ? bp['视频元素']['人物'] : []).map(p => p?.speakerId));
  if (voices.some(v => !people.has(v))) warnings.push('声线未绑定人物');
  let cursor = 0;
  const utterances = new Set();
  const shotIds = new Set();
  if (!shots.length) return ['缺少逐镜头拆解', ...warnings];
  for (const shot of shots) {
    let sid, start, end;
    try {
      sid = shot.shotId;
      start = finiteNumber(shot.start);
      end = finiteNumber(shot.end);
    } catch (_) {
      warnings.push('镜头缺少可用的ID或时间');
      continue;
    }
    if (shotIds.has(sid) || Math.abs(start - cursor) > 0.05 || end <= start) warnings.push('镜头ID重复或时间轴有空档/重叠');
    shotIds.add(sid);
    cursor = end;
    const frames = Array.isArray(shot.keyframes) ? shot.keyframes : [];
    if (!frames.length) warnings.push('镜头缺少代表帧');
    for (const frame of frames) {
      try {
        const t = finiteNumber(frame.time);
        if (!(start <= t && t < end)) warnings.push('代表帧越出镜头');
      } catch (_) { warnings.push('代表帧时间无效'); }
    }
    let lines = shot?.['声音']?.utterances;
    if (!Array.isArray(lines)) {
      warnings.push('utterances不是数组');
      lines = [];
    }
    for (const line of lines) {
      const uid = line?.utteranceId;
      const speaker = line?.speakerId;
      if (!uid || utterances.has(uid) || !voices.includes(speaker) || speaker === 'unknown') warnings.push('对白重复或说话人未绑定');
      if (uid) utterances.add(uid);
      try {
        const a = finiteNumber(line.start), b = finiteNumber(line.end);
        if (!(start <= a && a < b && b <= end)) warnings.push('对白超出镜头');
      } catch (_) { warnings.push('对白时间无效'); }
      for (const field of ['text', 'emotion', 'intensity', 'onScreen', 'lipSync']) {
        if (!(field in (line || {}))) warnings.push('对白缺少' + field);
      }
    }
  }
  if (duration != null && Math.abs(cursor - Number(duration)) > 0.1) warnings.push('蓝图未覆盖目标时长');
  const rhythm = bp['节奏结构'] || {};
  const cuts = rhythm.cutPlan;
  const beats = rhythm.dramaticBeats;
  if (!Array.isArray(cuts) || !Array.isArray(beats)) return [...new Set([...warnings, '缺少cutPlan/dramaticBeats'])];
  const expected = shots.slice(1).map(s => Number(s.start));
  let cutsMismatch = cuts.length !== expected.length;
  if (!cutsMismatch) {
    for (let i = 0; i < cuts.length; i++) {
      try {
        if (Math.abs(finiteNumber(cuts[i].time) - expected[i]) > 0.05) cutsMismatch = true;
      } catch (_) { cutsMismatch = true; }
    }
  }
  if (cutsMismatch) warnings.push('cutPlan未与真实镜头边界逐一对应');
  for (const beat of beats) {
    try {
      const a = finiteNumber(beat.start), b = finiteNumber(beat.end);
      if (!(0 <= a && a < b && b <= cursor)) warnings.push('情绪节拍越界');
    } catch (_) { warnings.push('情绪节拍时间无效'); }
  }
  return [...new Set(warnings)];
}

function minDistance(value, candidates) {
  if (!candidates.length) return 0;
  let best = Infinity;
  for (const candidate of candidates) best = Math.min(best, Math.abs(value - candidate));
  return best;
}

function plannerV1(bp, config, policy) {
  const totalRaw = Number(config.targetDuration);
  if (!Number.isFinite(totalRaw) || !Number.isInteger(totalRaw) || totalRaw <= 0) throw new Error('targetDuration必须是正整数秒');
  const total = totalRaw;
  const limits = capability(policy, config.model);
  const count = Math.max(1, Math.ceil(total / limits.maxDuration));
  if (total < limits.minDuration * count) throw new Error('无法用最少合法Segment覆盖目标时长');
  const warnings = diagnose(bp, total, policy);
  const shots = bp['逐镜头拆解'];
  const cutPlan = bp?.['节奏结构']?.cutPlan;
  if (!Array.isArray(shots) || !shots.length || !Array.isArray(cutPlan)) throw new Error('videoBlueprint缺少可规划的镜头/cutPlan');
  const cuts = cutPlan.map(c => finiteNumber(c.time));
  const lines = [];
  for (const shot of shots) {
    const values = shot?.['声音']?.utterances;
    if (Array.isArray(values)) lines.push(...values);
  }
  const pauses = lines.map(u => Number(u?.end)).filter(Number.isFinite);
  const boundaryCandidates = [...cuts, ...pauses];

  let states = new Map([[0, { cost: 0, windows: [] }]]);
  for (let index = 0; index < count; index++) {
    const following = new Map();
    for (const [start, state] of states.entries()) {
      for (let length = limits.minDuration; length <= limits.maxDuration; length++) {
        const end = start + length;
        const left = count - index - 1;
        if (!(left * limits.minDuration <= total - end && total - end <= left * limits.maxDuration)) continue;
        const split = lines.some(u => Number(u?.start) < end && end < Number(u?.end));
        const distance = minDistance(end, boundaryCandidates);
        const score = state.cost +
          (end === total ? 0 : policy.scoring.utteranceSplitPenalty * (split ? 1 : 0) + policy.scoring.boundaryDistanceWeight * distance) +
          policy.scoring.lengthBalanceWeight * Math.pow(length - total / count, 2);
        const existing = following.get(end);
        if (!existing || score < existing.cost) following.set(end, { cost: score, windows: [...state.windows, [start, end]] });
      }
    }
    states = following;
  }
  if (!states.has(total)) throw new Error('无法得到最少合法分段');

  const sourceDuration = Number.isFinite(Number(config.sourceDuration)) ? Number(config.sourceDuration) : total;
  const durationAdjustment = Number((total - sourceDuration).toFixed(6));
  if (config.targetDurationSource === 'source_nearest_integer' && Math.abs(durationAdjustment) > policy.timing.sourceDurationTolerance) {
    throw new Error('原片时长与最近整数秒目标差异超过允许范围');
  }
  const sourceTailPadding = Number(Math.max(0, durationAdjustment).toFixed(6));
  const segments = [];
  const windows = states.get(total).windows;

  for (let index = 0; index < windows.length; index++) {
    const [start, end] = windows[index];
    const byTime = new Map();
    for (const shot of shots) {
      const frames = Array.isArray(shot.keyframes) ? shot.keyframes : [];
      for (const frame of frames) {
        const t = Number(frame?.time);
        if (Number.isFinite(t) && start < t && t < end - policy.timing.endSafetyMargin) {
          byTime.set(t, [Number(frame?.priority || 1), t, shot.shotId]);
        }
      }
    }
    const candidates = [...byTime.values()].sort((a, b) => (b[0] - a[0]) || (b[1] - a[1]) || String(b[2]).localeCompare(String(a[2])));
    const representatives = [], extras = [], represented = new Set();
    for (const candidate of candidates) {
      if (represented.has(candidate[2])) extras.push(candidate);
      else { representatives.push(candidate); represented.add(candidate[2]); }
    }
    const orderedCandidates = [...representatives, ...extras];
    const size = limits.anchorCount;
    const sourceSafeEnd = Math.max(start + 0.01, sourceDuration - policy.timing.endSafetyMargin);
    const chosen = [[start, 'boundary'], [Math.min(end - policy.timing.endSafetyMargin, sourceSafeEnd), 'boundary']];
    for (const [, t, sid] of orderedCandidates) {
      if (chosen.length >= size) break;
      if (chosen.every(([v]) => Math.abs(t - v) > policy.timing.anchorMinDistance)) chosen.push([t, sid]);
    }
    while (chosen.length < size) {
      const ordered = [...chosen].sort((a, b) => a[0] - b[0]);
      let bestA = ordered[0], bestB = ordered[1], bestGap = bestB[0] - bestA[0];
      for (let i = 1; i < ordered.length - 1; i++) {
        const gap = ordered[i + 1][0] - ordered[i][0];
        if (gap > bestGap) { bestGap = gap; bestA = ordered[i]; bestB = ordered[i + 1]; }
      }
      chosen.push([(bestA[0] + bestB[0]) / 2, 'coverage']);
    }
    chosen.sort((a, b) => a[0] - b[0]);
    const anchors = chosen.map(([t, sid], i) => ({
      timestamp: Number(t.toFixed(6)),
      shotId: sid,
      anchorRole: i === 0 ? 'hard' : 'soft',
      eventType: i === 0 ? (index === 0 ? 'first_frame' : 'continuity_start') : 'context',
      semanticSource: 'unobserved'
    }));
    segments.push({
      segmentId: index + 1,
      globalStart: start,
      globalEnd: end,
      duration: end - start,
      anchors,
      boundaryOffset: end < total ? minDistance(end, boundaryCandidates) : 0,
      sourceFrameEnd: Number(Math.min(end, sourceDuration).toFixed(6)),
      tailPaddingSeconds: Number(Math.max(0, end - sourceDuration).toFixed(6))
    });
  }

  const technicalCuts = Array.isArray(config.technicalCutCandidates) ? config.technicalCutCandidates.map(Number).filter(Number.isFinite) : [];
  const unresolvedCuts = technicalCuts.filter(c => c < total && cuts.every(t => Math.abs(c - t) > policy.timing.unresolvedCutTolerance));
  return {
    schemaVersion: PLAN_SCHEMA_VERSION,
    plannerVersion: '1',
    policyVersion: policy.policyVersion,
    sourceDuration: Number(sourceDuration.toFixed(6)),
    targetDuration: total,
    durationAdjustmentSeconds: durationAdjustment,
    sourceTailPaddingSeconds: sourceTailPadding,
    sourceFrameClampApplied: sourceDuration < total,
    segments,
    unresolvedCuts,
    blueprintWarnings: warnings
  };
}

try {
  if (input.errorCode) return [{ json: input }];
  const videoBlueprint = asObject(input.videoBlueprint, 'videoBlueprint');
  const config = input.userConfig && typeof input.userConfig === 'object' ? input.userConfig : {};
  const requestedVersion = String(input.plannerVersion || DEFAULT_PLANNER_VERSION).trim() || DEFAULT_PLANNER_VERSION;
  const policy = POLICIES[requestedVersion === '2' ? '1' : requestedVersion];
  if (!policy) throw new Error('不支持的plannerVersion：' + requestedVersion);

  let replicationPlan;
  switch (requestedVersion) {
    case '2':
      replicationPlan = plannerV2(videoBlueprint, config, policy);
      break;
    case '1':
      replicationPlan = plannerV1(videoBlueprint, config, policy);
      break;
    default:
      throw new Error('未实现的plannerVersion：' + requestedVersion);
  }

  return [{
    json: {
      ...input,
      videoBlueprint: JSON.stringify(videoBlueprint),
      replicationPlan
    }
  }];
} catch (error) {
  return [{
    json: {
      ...input,
      errorCode: 'PLANNING_FAILED',
      message: error.message || '服务端复刻规划失败',
      replicationPlan: null
    }
  }];
}

// Appended to the versioned n8n Planner node. V1 remains unchanged.
function validateBlueprintV2(bp, duration) {
  const fail = message => { throw new Error(message); };
  const number = x => typeof x === 'number' && Number.isFinite(x);
  const roster = (items, key) => {
    if (!Array.isArray(items)) fail(key + '清单必须是数组');
    const map = new Map();
    for (const item of items) {
      const id = item?.[key];
      if (typeof id !== 'string' || !id.trim() || map.has(id)) fail(key + '缺失或重复');
      map.set(id, item);
    }
    return map;
  };
  const ids = (list, known, name) => {
    if (!Array.isArray(list) || new Set(list).size !== list.length || list.some(x => typeof x !== 'string' || !known.has(x))) fail(name + '无效或引用不存在的ID');
    return list;
  };
  if (bp.schemaVersion !== '7.0') fail('V2要求Blueprint 7.0');
  const people = roster(bp['视频元素']?.['人物'], 'characterId');
  const products = roster(bp['视频元素']?.['产品'], 'productId');
  const voices = roster(bp['声音结构']?.voiceProfiles, 'speakerId');
  for (const voice of voices.values()) {
    if (voice.characterId != null && !people.has(voice.characterId)) fail('声源关联不存在的人物');
  }
  const shots = bp['逐镜头拆解'];
  roster(shots, 'shotId');
  if (!shots.length) fail('缺少逐镜头拆解');
  let cursor = 0;
  const seenPeople = new Set(), seenProducts = new Set(), utterances = new Set();
  for (const shot of shots) {
    const {start:a, end:b} = shot;
    if (!number(a) || !number(b) || b <= a || Math.abs(a-cursor) > .05) fail('镜头时间无效或存在空档/重叠');
    cursor = b;
    ids(shot.visibleCharacterIds, people, 'visibleCharacterIds').forEach(x => seenPeople.add(x));
    ids(shot.productIds, products, 'productIds').forEach(x => seenProducts.add(x));
    if (!Array.isArray(shot.keyframes) || !shot.keyframes.length) fail('缺少keyframes');
    for (const frame of shot.keyframes) if (!number(frame.time) || frame.time < a || frame.time >= b) fail('keyframe越界');
    if (!Array.isArray(shot['声音']?.utterances)) fail('utterances必须是数组');
    for (const line of shot['声音'].utterances) {
      if (typeof line.utteranceId !== 'string' || !line.utteranceId || utterances.has(line.utteranceId) || !voices.has(line.speakerId)) fail('utteranceId重复/缺失或speakerId不存在');
      utterances.add(line.utteranceId);
      if (!number(line.start) || !number(line.end) || !(a <= line.start && line.start < line.end && line.end <= b)) fail('对白时间越界');
    }
  }
  if (!number(duration) || Math.abs(cursor-duration) > .1) fail('蓝图未覆盖目标时长');
  if (people.size !== seenPeople.size || products.size !== seenProducts.size) fail('实体清单与镜头引用不一致');
  for (const [id, person] of people) {
    const t = person.referenceTime;
    if (!number(t) || !shots.some(s => s.start <= t && t < s.end && s.visibleCharacterIds.includes(id))) fail('人物referenceTime未落在其出镜镜头');
  }
  const cuts = bp['节奏结构']?.cutPlan;
  if (!Array.isArray(cuts) || cuts.length !== shots.length-1) fail('cutPlan未覆盖相邻镜头');
  cuts.forEach((c,i) => {
    if (!number(c.time) || Math.abs(c.time-shots[i+1].start) > .05 || c.fromShotId !== shots[i].shotId || c.toShotId !== shots[i+1].shotId) fail('cutPlan边界引用错误');
  });
}

function plannerV2(bp, config, basePolicy) {
  validateBlueprintV2(bp, config.targetDuration);
  // The engine and duration policy are unchanged; only V2 evidence selection changes.
  const policy = JSON.parse(JSON.stringify(basePolicy));
  policy.blueprintSchemaVersion = '7.0';
  policy.policyVersion = '2.0.0';
  const working = JSON.parse(JSON.stringify(bp));
  const originalShots = bp['逐镜头拆解'];
  const people = bp['视频元素']['人物'];
  for (const shot of working['逐镜头拆解']) {
    for (const person of people) {
      if (shot.visibleCharacterIds.includes(person.characterId) && shot.start <= person.referenceTime && person.referenceTime < shot.end) {
        const frame = shot.keyframes.find(f => Math.abs(f.time-person.referenceTime) < .001);
        if (frame) frame.priority = Math.max(5, Number(frame.priority || 1));
        else shot.keyframes.push({time:person.referenceTime, priority:5, reason:'人物清晰出现定位'});
      }
    }
  }
  const plan = plannerV1(working, config, policy);
  plan.plannerVersion = '2';
  plan.policyVersion = '2.0.0';
  // diagnose V1 assumes a voice/person bijection; that diagnostic is invalid in V2.
  plan.blueprintWarnings = plan.blueprintWarnings.filter(x => x !== '声线未绑定人物');
  plan.reviewIssues = Array.isArray(bp.reviewIssues) ? bp.reviewIssues : [];
  for (const segment of plan.segments) {
    const shots = originalShots.filter(s => s.start < segment.globalEnd && s.end > segment.globalStart);
    segment.shotIds = shots.map(s => s.shotId);
    segment.sourceCharacterIds = [...new Set(shots.flatMap(s => s.visibleCharacterIds))];
    segment.sourceProductIds = [...new Set(shots.flatMap(s => s.productIds))];
    for (const anchor of segment.anchors) {
      const shot = originalShots.find(s => s.start <= anchor.timestamp && anchor.timestamp < s.end);
      if (!shot || anchor.timestamp < 0 || anchor.timestamp >= Number(plan.sourceDuration)) throw new Error('anchor无真实镜头或超出原片');
      anchor.selectionReason = ['boundary','coverage'].includes(anchor.shotId) ? anchor.shotId : 'keyframe';
      anchor.shotId = shot.shotId;
      // Shot-wide membership is not per-frame observed visibility.
      anchor.shotCharacterIds = shot.visibleCharacterIds;
      anchor.shotProductIds = shot.productIds;
    }
  }
  return plan;
}
